function birthDateFromNationalId(id?:string){
 const s=String(id||'').replace(/\D/g,'');if(s.length!==14)return '';
 const century=s[0]==='2'?1900:2000;return `${century+Number(s.slice(1,3))}-${s.slice(3,5)}-${s.slice(5,7)}`;
}
